#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int is_leap(int y)
{
    return (y % 4 == 0) && (y % 100 != 0 || y % 400 == 0);
}

int main(int argc, char *argv[])
{
    /* The original binary prints “INVALID” for any situation that is
       not a correct date in the exact format YYYY‑MM‑DD.  It also prints
       “INVALID” when the number of arguments is not exactly two. */
    if (argc != 2) {
        puts("INVALID");
        return 0;
    }

    const char *s = argv[1];

    /* Length must be exactly 10 characters. */
    if (strlen(s) != 10) {
        puts("INVALID");
        return 0;
    }

    /* The two dash characters must be at positions 4 and 7. */
    if (s[4] != '-' || s[7] != '-') {
        puts("INVALID");
        return 0;
    }

    /* All other characters must be decimal digits. */
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;          /* skip the dashes */
        if (!isdigit((unsigned char)s[i])) {
            puts("INVALID");
            return 0;
        }
    }

    /* Parse year, month and day. */
    int year  = (s[0] - '0') * 1000 + (s[1] - '0') * 100 +
                (s[2] - '0') * 10   + (s[3] - '0');

    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* Basic range checks. */
    if (month < 1 || month > 12) {
        puts("INVALID");
        return 0;
    }
    if (day < 1) {
        puts("INVALID");
        return 0;
    }

    /* Days in each month (non‑leap year). */
    static const int dim[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };

    int max_day = dim[month - 1];
    if (month == 2 && is_leap(year))
        max_day = 29;

    if (day > max_day) {
        puts("INVALID");
        return 0;
    }

    /* All checks passed – the date is valid. */
    puts("VALID");
    return 0;
}
